<?php require 'functions.php';$items=load_data('addresses');if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$items=array_filter($items,fn($x)=>(int)$x['id']!==$id);save_data('addresses',$items);redirect('addresses.php','Endereço excluído.');}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$row=['id'=>$id?:next_id($items),'label'=>trim($_POST['label']),'street'=>trim($_POST['street']),'number'=>trim($_POST['number']),'city'=>trim($_POST['city']),'state'=>trim($_POST['state']),'cep'=>trim($_POST['cep'])];if($id){foreach($items as &$x){if((int)$x['id']===$id){$x=$row;break;}}}else{$items[]=$row;}save_data('addresses',$items);redirect('addresses.php',$id?'Endereço atualizado.':'Endereço cadastrado.');}$edit=isset($_GET['edit'])?find_by_id($items,(int)$_GET['edit']):null;$title='Endereços';require 'header.php';?>
<h2 class="page-title">Endereços</h2><div class="row g-4"><div class="col-lg-4"><div class="card p-4"><h5><?=$edit?'Editar':'Novo'?> endereço</h5><form method="post"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label class="form-label">Identificação</label><input required class="form-control mb-2" name="label" placeholder="Ex.: Depósito Central" value="<?=h($edit['label']??'')?>"><label class="form-label">Rua</label><input required class="form-control mb-2" name="street" value="<?=h($edit['street']??'')?>"><label class="form-label">Número</label><input required class="form-control mb-2" name="number" value="<?=h($edit['number']??'')?>"><label class="form-label">Cidade</label><input required class="form-control mb-2" name="city" value="<?=h($edit['city']??'')?>"><label class="form-label">UF</label><input required maxlength="2" class="form-control mb-2" name="state" value="<?=h($edit['state']??'')?>"><label class="form-label">CEP</label><input class="form-control mb-3" name="cep" value="<?=h($edit['cep']??'')?>"><button class="btn btn-primary w-100">Salvar</button></form></div></div><div class="col-lg-8"><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Identificação</th><th>Local</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=$x['id']?></td><td><?=h($x['label'])?></td><td><?=h($x['city'].'/'.$x['state'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$x['id']?>">Editar</a> <a onclick="return confirm('Excluir?')" class="btn btn-sm btn-outline-danger" href="?delete=<?=$x['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require 'footer.php';?>
